"贵":{"k":"貴 귀할 귀","r":"贝","p":["中","一","贝"],"o":"","m":"돈(贝) 위에 쌓인 것 — 비싸다, 귀하다.","lv":1},
"国":{"k":"國 나라 국","r":"囗","p":["囗","玉"],"o":"번체 國은 국경(囗) 안을 창(戈)으로 지키는 모양. 간체는 국경 안에 玉(보물)을 넣었다.","m":"울타리(囗) 안에 보물(玉)을 지키는 곳 = 나라.","lv":1},
"还":{"k":"還 돌아올 환","r":"辶","p":["辶","不"],"o":"가지(辶) 않음(不) → 돌아오다. 부사로는 '아직(hái)'.","m":"가다가(辶) 안(不) 가고 돌아온다 — 아직, 또.","lv":1},
