"听":{"k":"聽 들을 청","r":"口","p":["口","斤"],"o":"간체는 口+斤. 번체 聽은 귀(耳)로 곧게 듣는 모양.","m":"입(口)으로 한 말이 도끼(斤)처럼 꽂히게 듣는다.","lv":1},
