"放心":["放(놓다) + 心(마음) → 마음을 놓다 = 안심하다","你放心，我会照顾好自己。","안심해요, 내 몸은 내가 잘 챙길게요."],
"放学":["放(풀어주다) + 学(학교) → 학교에서 풀어주다 = 하교하다","孩子四点放学。","아이는 4시에 하교해요."],
"分开":["分(나누다) + 开(열다) → 갈라놓다 = 헤어지다","我们分开走吧。","우리 따로 가요."],
"风":["","今天风很大。","오늘 바람이 세요."],
"封":["","我给她写了一封信。","그녀에게 편지 한 통을 썼어요."],
"服务":["服(따르다) + 务(일) → 따르며 일하다 = 서비스","这家饭店的服务很好。","이 식당은 서비스가 좋아요."],
"附近":["附(붙다) + 近(가깝다) → 가까이 붙은 곳 = 근처","附近有银行吗？","근처에 은행 있어요?"],
"复习":["复(다시) + 习(익히다) → 다시 익히다 = 복습하다","考试前要好好儿复习。","시험 전에 잘 복습해야 해요."],
"夫妻":["夫(남편) + 妻(아내) → 부부","他们是一对老夫妻。","그들은 노부부예요."],
"该":["","我该走了。","이제 가야겠어요."],
"感到":["感(느끼다) + 到(이르다) → 느끼다","我感到很高兴。","나는 아주 기뻐요."],
