"感兴趣":["感(느끼다) + 兴趣(흥미) → 흥미를 느끼다","我对中国文化很感兴趣。","나는 중국 문화에 관심이 많아요."],
"干":["","你在干什么？","뭐 하고 있어요?"],
"干净":["干(마르다) + 净(깨끗하다) → 깨끗하다","房间打扫得很干净。","방이 깨끗하게 청소됐어요."],
"刚":["","我刚到家。","방금 집에 도착했어요."],
"刚才":["刚(막) + 才(비로소) → 방금 전","刚才有人给你打电话。","방금 누가 당신에게 전화했어요."],
"刚刚":["刚(막)을 두 번 → 방금, 막","电影刚刚开始。","영화가 방금 시작했어요."],
