"工作日":["工作(일) + 日(날) → 일하는 날 = 평일","工作日我没有时间。","평일에는 시간이 없어요."],
"公斤":["公(공식) + 斤(근) → 공식 단위 무게 = 킬로그램","我买了两公斤苹果。","사과 2킬로그램을 샀어요."],
"公园":["公(공공) + 园(동산) → 모두의 동산 = 공원","公园里有很多人。","공원에 사람이 많아요."],
"故事":["故(옛) + 事(일) → 옛날 일 = 이야기","奶奶给我讲故事。","할머니가 이야기를 들려주세요."],
"刮":["","外面刮大风了。","밖에 바람이 세게 불어요."],
