"关机":["关(끄다) + 机(기계) → 기계를 끄다","上课的时候请关机。","수업 시간에는 휴대폰을 꺼 주세요."],
"关系":["关(빗장, 관계) + 系(매다) → 서로 묶인 것 = 관계","我们的关系很好。","우리는 사이가 좋아요."],
"关心":["关(관계하다) + 心(마음) → 마음을 쓰다 = 관심을 갖다","谢谢你的关心。","관심 가져 줘서 고마워요."],
"关于":["关(관계하다) + 于(~에) → ~에 관해","这是一本关于中国历史的书。","이건 중국 역사에 관한 책이에요."],
"关注":["关(관계하다) + 注(쏟다) → 관심을 쏟다, 팔로우하다","很多人关注这个问题。","많은 사람이 이 문제에 관심을 가져요."],
"国家":["国(나라) + 家(집) → 나라 = 국가","你去过哪些国家？","어떤 나라들에 가 봤어요?"],
"过节":["过(보내다) + 节(명절) → 명절을 쇠다","过节的时候我们全家在一起。","명절에는 온 가족이 함께 있어요."],
