"黑板":["黑(검다) + 板(판) → 검은 판 = 칠판","老师在黑板上写字。","선생님이 칠판에 글씨를 써요."],
"后来":["后(뒤) + 来(오다) → 뒤에 온 때 = 그 후","后来他去了中国。","그 후에 그는 중국에 갔어요."],
