"花园":["花(꽃) + 园(동산) → 꽃동산 = 정원","我家后面有一个小花园。","우리 집 뒤에 작은 정원이 있어요."],
"画家":["画(그림) + 家(전문가) → 그림 전문가 = 화가","她想当一个画家。","그녀는 화가가 되고 싶어 해요."],
"环境":["环(둘레) + 境(경계, 형편) → 둘러싼 형편 = 환경","这里的环境很好。","여기는 환경이 좋아요."],
