"黄色":["黄(누렇다) + 色(빛깔) → 노란색","她穿着一条黄色的裙子。","그녀는 노란 치마를 입고 있어요."],
"回答":["回(돌려주다) + 答(대답하다) → 대답하다","请回答我的问题。","제 질문에 대답해 주세요."],
