"节目":["节(마디) + 目(항목) → 순서대로 나오는 항목 = 프로그램","这个电视节目很有意思。","이 TV 프로그램 아주 재미있어요."],
"节日":["节(명절) + 日(날) → 명절","春节是中国最重要的节日。","춘절은 중국에서 가장 중요한 명절이에요."],
"结婚":["结(맺다) + 婚(혼인) → 혼인을 맺다 = 결혼하다","他们明年结婚。","그들은 내년에 결혼해요."],
