"句":["","请说一句话。","한마디 해 주세요."],
"句子":["句(구절) + 子(명사 꼬리) → 문장","请用这个词造一个句子。","이 단어로 문장을 하나 만드세요."],
"决定":["决(결단하다) + 定(정하다) → 결정하다","我决定明年去中国留学。","내년에 중국으로 유학 가기로 결정했어요."],
