"开机":["开(켜다) + 机(기계) → 전원을 켜다","下课以后可以开机。","수업 끝나면 휴대폰을 켜도 돼요."],
"开心":["开(열리다) + 心(마음) → 마음이 열리다 = 즐겁다","今天玩儿得很开心。","오늘 정말 즐겁게 놀았어요."],
"看来":["看(보다) + 来(오다) → 보아하니","看来他今天不会来了。","보아하니 그는 오늘 안 오겠네요."],
