"青年":["青(푸르다, 젊다) + 年(나이) → 청년","他是一个有理想的青年。","그는 꿈이 있는 청년이에요."],
"轻":["","这个箱子很轻。","이 상자는 가벼워요."],
"轻松":["轻(가볍다) + 松(느슨하다) → 홀가분하다","考完试，我觉得很轻松。","시험이 끝나니 홀가분해요."],
"情况":["情(사정) + 况(상황) → 상황","现在的情况怎么样？","지금 상황이 어때요?"],
"庆祝":["庆(경사) + 祝(축하하다) → 경축하다","我们一起庆祝他的生日。","우리 함께 그의 생일을 축하해요."],
"球队":["球(공) + 队(팀) → 구기 팀","我们的球队赢了。","우리 팀이 이겼어요."],
"球迷":["球(공) + 迷(빠지다) → 공에 빠진 사람 = 팬","他是一个足球迷。","그는 축구광이에요."],
"区":["","我住在海淀区。","나는 하이뎬구에 살아요."],
"区别":["区(나누다) + 别(다르다) → 구별, 차이","这两个词有什么区别？","이 두 단어는 무슨 차이가 있어요?"],
"取":["","我去银行取钱。","은행에 돈 찾으러 가요."],
"取得":["取(가지다) + 得(얻다) → 얻다","他取得了很好的成绩。","그는 좋은 성적을 거뒀어요."],
"取消":["取(가지다) + 消(없애다) → 취소하다","因为下雨，比赛取消了。","비 때문에 시합이 취소됐어요."],
"全":["","全班同学都来了。","반 친구 전원이 왔어요."],
"全部":["全(온전히) + 部(부분) → 전부","我把作业全部做完了。","숙제를 전부 끝냈어요."],
"全都":["全(모두) + 都(모두) → 모두","他们全都是我的朋友。","그들은 모두 내 친구예요."],
"全球":["全(온) + 球(지구) → 전 세계","这个问题全球都很关注。","이 문제는 전 세계가 주목해요."],
"全身":["全(온) + 身(몸) → 온몸","我跑完步全身都是汗。","뛰고 나니 온몸이 땀투성이예요."],
"缺":["","这里缺水。","여기는 물이 부족해요."],
"缺点":["缺(모자라다) + 点(점) → 단점","每个人都有缺点。","누구에게나 단점이 있어요."],
"缺少":["缺(모자라다) + 少(적다) → 부족하다","我们缺少一个人。","우리는 한 명이 모자라요."],
"却":["","他很累，却不想休息。","그는 피곤한데도 쉬려고 하지 않아요."],
"确实":["确(확실하다) + 实(참) → 확실히","这个办法确实很好。","이 방법은 확실히 좋아요."],
"然而":["然(그러하다) + 而(그러나) → 그러나","他很努力，然而没有成功。","그는 노력했지만 성공하지 못했어요."],
"热闹":["热(뜨겁다) + 闹(시끄럽다) → 떠들썩하다","过年的时候很热闹。","설에는 아주 북적거려요."],
"人生":["人(사람) + 生(삶) → 인생","人生很短，要好好儿珍惜。","인생은 짧으니 소중히 해야 해요."],
"人数":["人(사람) + 数(수) → 인원수","今天来的人数很多。","오늘 온 사람 수가 많아요."],
"人员":["人(사람) + 员(구성원) → 인원, 요원","工作人员正在准备。","직원들이 준비하고 있어요."],
"任何":["任(맡기다, 아무) + 何(어느) → 어떠한","有任何问题都可以问我。","어떤 질문이든 나에게 물어봐도 돼요."],
"任务":["任(맡다) + 务(일) → 맡은 일 = 임무","我完成了今天的任务。","오늘 할 일을 끝냈어요."],
