"仍然":["仍(여전히) + 然(그러하다) → 여전히","天很冷，他仍然去跑步了。","날이 추운데도 그는 여전히 달리러 갔어요."],
"日常":["日(날) + 常(늘) → 일상","这些都是日常用品。","이것들은 다 일상용품이에요."],
"日记":["日(날) + 记(기록) → 일기","我每天写日记。","나는 매일 일기를 써요."],
"日期":["日(날) + 期(때) → 날짜","请写上今天的日期。","오늘 날짜를 써 주세요."],
"日子":["日(날) + 子(명사 꼬리) → 날, 생활","今天是个好日子。","오늘은 좋은 날이에요."],
"入":["","请从这里入场。","여기로 입장하세요."],
"入口":["入(들어가다) + 口(입구) → 입구","入口在那边。","입구는 저쪽이에요."],
"入学":["入(들어가다) + 学(학교) → 입학하다","他九月入学。","그는 9월에 입학해요."],
"散步":["散(흩어지다, 거닐다) + 步(걸음) → 거닐다 = 산책하다","吃完饭我们去散步吧。","밥 먹고 산책 가요."],
"森林":["森(빽빽한 숲) + 林(숲) → 숲","森林里有很多动物。","숲에는 동물이 많아요."],
"伤心":["伤(다치다) + 心(마음) → 마음을 다치다 = 슬퍼하다","别伤心了。","슬퍼하지 마요."],
