"商品":["商(장사) + 品(물건) → 상품","这家店的商品很多。","이 가게는 상품이 많아요."],
"上门":["上(나아가다) + 门(문) → 문 앞으로 가다 = 방문하다","他们可以上门修理。","그들은 방문 수리를 해 줘요."],
"稍":["","请稍等。","잠시만 기다려 주세요."],
"稍微":["稍(조금) + 微(작다) → 조금","请稍微大声一点儿。","조금만 크게 말해 주세요."],
"少见":["少(드물게) + 见(보이다) → 보기 드물다","这种鸟很少见。","이런 새는 보기 드물어요."],
"少量":["少(적은) + 量(양) → 소량","只要放少量的盐。","소금은 조금만 넣으면 돼요."],
"少年":["少(젊은, shào) + 年(나이) → 소년","他是一个快乐的少年。","그는 즐거운 소년이에요."],
"少数":["少(적은) + 数(수) → 소수","只有少数人同意。","소수만 동의했어요."],
"社会":["社(모이다) + 会(모임) → 사회","我们要为社会做贡献。","우리는 사회에 기여해야 해요."],
"摄氏度":["摄氏(섭씨) + 度(도) → 섭씨 온도","今天最高气温三十摄氏度。","오늘 최고 기온은 섭씨 30도예요."],
"申请":["申(펴다) + 请(청하다) → 신청하다","我申请了这所大学。","나는 이 대학에 지원했어요."],
