"深":["","这条河很深。","이 강은 아주 깊어요."],
"甚至":["甚(심하다) + 至(이르다) → 심지어","他忙得甚至没时间吃饭。","그는 바빠서 심지어 밥 먹을 시간도 없어요."],
"生":["","她生了一个女儿。","그녀는 딸을 낳았어요."],
"生命":["生(살다) + 命(목숨) → 생명","生命是最宝贵的。","생명은 가장 소중해요."],
