"师傅":["师(스승) + 傅(스승) → 기사님, 장인","师傅，去火车站。","기사님, 기차역 가 주세요."],
"师生":["师(선생) + 生(학생) → 선생님과 학생","全校师生都参加了运动会。","전교 교사와 학생이 모두 운동회에 참가했어요."],
