"时间表":["时间(시간) + 表(표) → 시간표","请看一下火车时间表。","기차 시간표를 좀 보세요."],
"实际":["实(참) + 际(사이, 때) → 실제","实际情况不是这样的。","실제 상황은 그렇지 않아요."],
"实际上":["实际(실제) + 上(~상) → 사실상","实际上，他已经知道了。","사실 그는 이미 알고 있었어요."],
"实在":["实(참) + 在(있다) → 정말","这里的菜实在太好吃了。","여기 음식은 정말 너무 맛있어요."],
"食品":["食(먹을 것) + 品(물건) → 식품","这家超市的食品很新鲜。","이 슈퍼의 식품은 아주 신선해요."],
"食堂":["食(먹다) + 堂(집) → 구내식당","我们在学校食堂吃饭。","우리는 학교 식당에서 밥을 먹어요."],
"食物":["食(먹을 것) + 物(물건) → 음식물","不要浪费食物。","음식을 낭비하지 마세요."],
"使":["","这件事使我很高兴。","이 일은 나를 아주 기쁘게 했어요."],
"使用":["使(부리다) + 用(쓰다) → 사용하다","这个电脑很容易使用。","이 컴퓨터는 사용하기 쉬워요."],
"世纪":["世(세상) + 纪(벼리, 시대) → 세기","现在是二十一世纪。","지금은 21세기예요."],
"市场":["市(시장) + 场(마당) → 시장","我去市场买菜。","시장에 장 보러 가요."],
"市区":["市(도시) + 区(구역) → 시내","我家离市区很远。","우리 집은 시내에서 멀어요."],
"视频":["视(보다) + 频(주파수) → 보는 영상 = 동영상","我在网上看视频。","인터넷에서 영상을 봐요."],
"试题":["试(시험) + 题(문제) → 시험 문제","这次的试题很难。","이번 시험 문제는 어려웠어요."],
"是否":["是(옳다) + 否(아니다) → ~인지 아닌지","我不知道他是否会来。","그가 올지 안 올지 모르겠어요."],
"适合":["适(알맞다) + 合(맞다) → 적합하다","这个工作很适合你。","이 일은 당신에게 잘 맞아요."],
"适应":["适(알맞다) + 应(응하다) → 적응하다","我已经适应了这里的天气。","여기 날씨에 이미 적응했어요."],
"收费":["收(거두다) + 费(비용) → 요금을 받다","这个停车场怎么收费？","이 주차장은 요금을 어떻게 받아요?"],
"收入":["收(거두다) + 入(들이다) → 수입","他的收入很高。","그는 수입이 많아요."],
"收拾":["收(거두다) + 拾(줍다) → 정리하다","快把房间收拾一下。","얼른 방 좀 치워요."],
"收听":["收(받다) + 听(듣다) → 청취하다","我每天收听新闻。","나는 매일 뉴스를 들어요."],
"首":["","我会唱这首歌。","나는 이 노래를 부를 줄 알아요."],
"首都":["首(머리) + 都(도읍) → 으뜸 도읍 = 수도","北京是中国的首都。","베이징은 중국의 수도예요."],
"首先":["首(머리) + 先(먼저) → 맨 먼저","首先，我要感谢大家。","먼저 여러분께 감사드려요."],
"受不了":["受(견디다) + 不了(할 수 없다) → 견딜 수 없다","太热了，我受不了了。","너무 더워서 못 참겠어요."],
"受伤":["受(당하다) + 伤(상처) → 다치다","他踢球的时候受伤了。","그는 축구하다가 다쳤어요."],
"输":["","我们队输了。","우리 팀이 졌어요."],
"熟":["","这个苹果还没熟。","이 사과는 아직 안 익었어요."],
"熟悉":["熟(익다) + 悉(다 알다) → 잘 알다","我对这里很熟悉。","나는 여기를 잘 알아요."],
"暑假":["暑(더위) + 假(휴가) → 여름 방학","暑假我们去海边吧。","여름 방학에 바닷가에 가요."],
"树林":["树(나무) + 林(숲) → 숲","树林里很安静。","숲속은 아주 조용해요."],
"数":["","请数一数有多少人。","사람이 몇 명인지 세어 보세요."],
"数量":["数(수) + 量(양) → 수량","这些东西的数量不多。","이 물건들은 수량이 많지 않아요."],
"数字":["数(수) + 字(글자) → 숫자","请写下这些数字。","이 숫자들을 적어 주세요."],
"帅":["","他长得很帅。","그는 잘생겼어요."],
"顺便":["顺(따르다) + 便(편하다) → 하는 김에","你去超市的时候，顺便帮我买瓶水。","슈퍼 가는 김에 물 한 병 사다 줘요."],
"顺利":["顺(순하다) + 利(이롭다) → 순조롭다","祝你一路顺利！","가시는 길 순조롭기를!"],
"顺序":["顺(따르다) + 序(차례) → 순서","请按顺序排队。","순서대로 줄을 서세요."],
"说法":["说(말하다) + 法(방법) → 말하는 방식 = 견해","这种说法不对。","이런 말은 틀려요."],
"说明":["说(말하다) + 明(밝히다) → 설명하다","请说明一下原因。","이유를 설명해 주세요."],
"说明书":["说明(설명) + 书(책) → 설명서","用之前请先看说明书。","사용하기 전에 먼저 설명서를 보세요."],
"硕士":["硕(크다) + 士(선비) → 큰 선비 = 석사","她是硕士研究生。","그녀는 석사 과정 학생이에요."],
"死":["","这棵树死了。","이 나무는 죽었어요."],
"速度":["速(빠르다) + 度(정도) → 속도","这辆车的速度很快。","이 차는 속도가 빨라요."],
"塑料":["塑(빚다) + 料(재료) → 빚어 만드는 재료 = 플라스틱","请少用塑料袋。","비닐봉지를 적게 써 주세요."],
"酸":["","这个苹果很酸。","이 사과는 아주 셔요."],
