"提出":["提(끌어올리다) + 出(내다) → 제기하다","他提出了一个好办法。","그가 좋은 방법을 제안했어요."],
"提到":["提(끌어올리다) + 到(이르다) → 언급하다","他在信中提到了你。","그는 편지에서 당신을 언급했어요."],
"提供":["提(내놓다) + 供(바치다) → 제공하다","酒店提供免费早餐。","호텔에서 무료 조식을 제공해요."],
"提前":["提(끌어올리다) + 前(앞) → 앞당기다","我们提前十分钟到了。","우리는 10분 일찍 도착했어요."],
"提醒":["提(끌어올리다) + 醒(깨우다) → 일깨우다","请提醒我明天早点儿起床。","내일 일찍 일어나라고 알려 주세요."],
