"体温":["体(몸) + 温(온도) → 체온","我量了一下体温，三十八度。","체온을 재 보니 38도예요."],
"体重":["体(몸) + 重(무게) → 체중","最近我的体重增加了。","요즘 체중이 늘었어요."],
