"停车":["停(멈추다) + 车(차) → 차를 세우다","这里不能停车。","여기는 주차할 수 없어요."],
"停车场":["停车(주차) + 场(마당) → 주차장","停车场在楼下。","주차장은 아래층에 있어요."],
"停止":["停(멈추다) + 止(그치다) → 정지하다","音乐停止了。","음악이 멈췄어요."],
