"通过":["通(통하다) + 过(지나다) → 통과하다, ~을 통해","我通过了考试。","시험에 합격했어요."],
"通知":["通(통하다) + 知(알리다) → 알리다","请通知大家明天开会。","모두에게 내일 회의한다고 알려 주세요."],
