"袜子":["袜(버선) + 子(명사 꼬리) → 양말","我买了三双袜子。","양말 세 켤레를 샀어요."],
"外出":["外(밖) + 出(나가다) → 외출하다","经理外出了，不在办公室。","매니저님은 외출하셔서 사무실에 안 계세요."],
"外套":["外(바깥) + 套(씌우다) → 겉에 걸치는 옷 = 외투","外面冷，穿上外套吧。","밖이 추우니 외투 입어요."],
