"无聊":["无(없다) + 聊(즐길 거리) → 즐길 거리가 없다 = 심심하다","周末在家很无聊。","주말에 집에 있으니 심심해요."],
"无论":["无(없다) + 论(따지다) → 따질 것 없이 = ~에 관계없이","无论多忙，我都会给你打电话。","아무리 바빠도 전화할게요."],
