"熊":["","熊在森林里生活。","곰은 숲에서 살아요."],
"修":["","他在修自行车。","그는 자전거를 고치고 있어요."],
"修理":["修(고치다) + 理(다스리다) → 수리하다","我的电脑需要修理。","내 컴퓨터는 수리가 필요해요."],
