"赚":["","他一个月赚很多钱。","그는 한 달에 돈을 많이 벌어요."],
"装":["","请把书装在包里。","책을 가방에 넣어 주세요."],
"准":["","这里不准停车。","여기는 주차 금지예요."],
"准确":["准(정확하다) + 确(확실하다) → 정확하다","你的发音很准确。","발음이 아주 정확해요."],
"准时":["准(정확하다) + 时(시간) → 정시에","火车准时到了。","기차가 정시에 도착했어요."],
"资料":["资(밑천) + 料(재료) → 자료","我在图书馆查资料。","도서관에서 자료를 찾아요."],
"仔细":["仔(자세하다) + 细(세밀하다) → 꼼꼼하다","请仔细看一下。","자세히 좀 보세요."],
"自":["","他自北京来。","그는 베이징에서 왔어요."],
"自然":["自(스스로) + 然(그러하다) → 스스로 그러함 = 자연","我喜欢大自然。","나는 자연을 좋아해요."],
"自信":["自(스스로) + 信(믿다) → 자신감","他是一个很自信的人。","그는 자신감 넘치는 사람이에요."],
"自学":["自(스스로) + 学(배우다) → 독학하다","我是自学汉语的。","나는 중국어를 독학했어요."],
"总结":["总(모으다) + 结(맺다) → 총정리하다","请总结一下今天学的内容。","오늘 배운 내용을 정리해 보세요."],
"租":["","我想租一套房子。","집을 하나 빌리고 싶어요."],
"组":["","我们组有五个人。","우리 조는 다섯 명이에요."],
"最终":["最(가장) + 终(끝) → 최종","最终我们赢了。","결국 우리가 이겼어요."],
"尊重":["尊(높이다) + 重(무겁다) → 존중하다","我们要尊重老人。","어른을 존중해야 해요."],
"左右":["左(왼) + 右(오른) → 좌우, 가량","他三十岁左右。","그는 서른 살쯤이에요."],
