"作为":["作(삼다) + 为(~로) → ~로서","作为学生，我们要好好学习。","학생으로서 우리는 열심히 공부해야 해요."],
"作文":["作(짓다) + 文(글) → 작문","我写了一篇作文。","작문을 한 편 썼어요."],
"作用":["作(하다) + 用(쓰다) → 작용, 역할","这个药有什么作用？","이 약은 무슨 효과가 있어요?"],
"作者":["作(짓다) + 者(사람) → 저자","这本书的作者是谁？","이 책의 저자가 누구예요?"],
