"座位":["座(자리) + 位(자리) → 좌석","这个座位有人吗？","이 자리 주인 있어요?"],
"做法":["做(하다) + 法(방법) → 하는 방법","这个菜的做法很简单。","이 요리는 만드는 법이 간단해요."],
"做梦":["做(하다) + 梦(꿈) → 꿈을 꾸다","我昨天晚上做梦了。","어젯밤에 꿈을 꿨어요."]
